export const onBrowser = typeof (window as any).GetParentResourceName === "undefined"

export const fetchNui = (eventName: string, data?: any) => new Promise(resolve => {
	if (onBrowser) return window.parent.fetchNui(eventName, data, resolve)

	const resourceName = (window as any).GetParentResourceName ? (window as any).GetParentResourceName() : 'nui-frame-app';

	fetch(`https://${resourceName}/${eventName}`, { // eslint-disable-line no-undef
		method: 'POST',
		headers: {'Content-Type': 'application/json; charset=UTF-8'},
		body: JSON.stringify(data)
	}).then(resp => resp.json())
		.then(r => resolve(r))
		.catch(err => console.log('NUI Error:', err))
})