import { AnimatePresence, motion } from 'framer-motion'
import { ReactNode, useState } from 'react'

export enum ToggleSizes {
	Small = 1,
	Default,
}
interface ToggleProps {
	id?: string
	isActive: boolean
	toggle: () => void
	size?: ToggleSizes
	enabled?: boolean
	children?: ReactNode | null
	className?: string
}

export default function Toggle({ id, isActive, toggle, size = ToggleSizes.Small, enabled = true, children = null, className = ''}: ToggleProps) {
	const [isInitialToggleLoad, setIsInitialToggleLoad] = useState(true)

	const switchToggle = () => {
		if (!enabled) return;

		toggle()
		if (isInitialToggleLoad) setIsInitialToggleLoad(false)
	}

	return (
		children ? (
			<div className={`flex flex-row justify-between cursor-pointer ${className}`} onClick={toggle}>
				{children}
				<button className={`flex w-fit h-fit cursor-pointer outline-none p-[4px] rounded-full transition-colors ${isActive ? "bg-emerald-500/40" : "bg-base-800/60"} ${enabled ? "opacity-100" : "opacity-50"}`} id={id} onClick={switchToggle}>
					<AnimatePresence initial={false}>
						<motion.span 
							animate={[isActive ? "active" : "inactive"]} 
							variants={{
								active: { marginLeft: size == ToggleSizes.Default ? "1.5em" : "1.15em", marginRight: "0em" },
								inactive: { marginRight: size == ToggleSizes.Default ? "1.5em" : "1.15em", marginLeft: "0em" },
							}} 
							className={`${size == ToggleSizes.Default ? "h-[20px] w-[20px]" : "h-[14px] w-[14px]"} transition-colors rounded-full ${isActive ? "bg-emerald-500" : "bg-base-700"}`} 
						/>
					</AnimatePresence>
				</button>
			</div>
		) : (
			<button className={`flex w-fit h-fit cursor-pointer outline-none p-[4px] rounded-full transition-colors ${isActive ? "bg-emerald-600/20" : "bg-transparent"} ${enabled ? "opacity-100" : "opacity-50"}`} id={id} onClick={switchToggle}>
				<AnimatePresence initial={false}>
					<motion.span 
						animate={[isActive ? "active" : "inactive"]} 
						variants={{
							active: { marginLeft: size == ToggleSizes.Default ? "1.5em" : "1.15em", marginRight: "0em" },
							inactive: { marginRight: size == ToggleSizes.Default ? "1.5em" : "1.15em", marginLeft: "0em" },
						}} 
						className={`${size == ToggleSizes.Default ? "h-[20px] w-[20px]" : "h-[14px] w-[14px]"} transition-colors rounded-full ${isActive ? "bg-emerald-800" : "bg-base-600"}`} 
					/>
				</AnimatePresence>
			</button>
		)
	)
}